const resources = this.serverless.service.provider.compiledCloudFormationTemplate.Resources;
const deploymentLogicalId = _.findKey(resources, (resource, logicalId) =>
  resource.Type === 'AWS::ApiGateway::Deployment' &&
  logicalId.startsWith('ApiGatewayDeployment')
);

if (deploymentLogicalId) {
  // The deployment ID changes on every package to force API Gateway to redeploy.
  // Allow custom resources to depend on it without knowing that generated ID.
  _.forEach(resources, (resource) => {
    if (Array.isArray(resource.DependsOn)) {
      resource.DependsOn = resource.DependsOn.map(dependency =>
        (dependency === 'ApiGatewayDeployment' ? deploymentLogicalId : dependency)
      );
    } else if (resource.DependsOn === 'ApiGatewayDeployment') {
      resource.DependsOn = deploymentLogicalId;
    }
  });
}

return BbPromise.resolve();

['ApiGatewayDeployment', ['OtherResource', 'ApiGatewayDeployment']].forEach(dependency => {
  it(`should resolve the deployment dependency ${JSON.stringify(dependency)}`, () => {
    const deploymentLogicalId = 'ApiGatewayDeployment123456789';
    coreCloudFormationTemplate.Resources[deploymentLogicalId] = {
      Type: 'AWS::ApiGateway::Deployment',
      DependsOn: ['ApiGatewayMethodUsersGet'],
    };
    serverless.service.resources = {
      Resources: {
        PathMapping: {
          Type: 'AWS::ApiGateway::BasePathMapping',
          DependsOn: dependency,
          Properties: { Stage: 'dev' },
        },
        OtherResource: { Type: 'Custom::Other', DependsOn: 'UnrelatedResource' },
      },
    };

    return awsPackage.mergeCustomProviderResources().then(() => {
      const resources = serverless.service.provider.compiledCloudFormationTemplate.Resources;
      expect(resources.PathMapping.DependsOn).to.deep.equal(
        Array.isArray(dependency) ?
          ['OtherResource', deploymentLogicalId] : deploymentLogicalId
      );
      expect(resources.PathMapping.Properties).to.deep.equal({ Stage: 'dev' });
      expect(resources[deploymentLogicalId].DependsOn)
        .to.deep.equal(['ApiGatewayMethodUsersGet']);
      expect(resources.OtherResource.DependsOn).to.equal('UnrelatedResource');
      expect(serverless.service.resources.Resources.PathMapping.DependsOn)
        .to.deep.equal(dependency);
    });
  });
});

it('should leave dependencies alone when no API deployment is generated', () => {
  serverless.service.resources = {
